IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };

Console.WriteLine(intList.Last());                    // 87
Console.WriteLine(intList.Last(i => i % 2 == 0));    // 50 (last even)

// emptyList.Last() throws InvalidOperationException

IList<int> intList = new List<int>() { 7, 10, 21, 30, 45, 50, 87 };
IList<string> emptyList = new List<string>();

Console.WriteLine(intList.LastOrDefault());                    // 87
Console.WriteLine(intList.LastOrDefault(i => i % 2 == 0));    // 50
Console.WriteLine(emptyList.LastOrDefault());                  // null (default string)
